+
+    private static string DescribeTermsrvState(TermsrvFileState state)
+    {
+        if (!state.Exists)
+        {
+            return "文件不存在";
+        }
+
+        if (!state.Verified)
+        {
+            return "暂时无法验证（需要管理员权限，或正在等待 sfc）";
+        }
+
+        return state.Intact ? "与系统组件库一致" : "与系统组件库不一致";
+    }
