+    /// <summary>
+    /// 确定性的短哈希（FNV-1a）。用 string.GetHashCode 不行：那个每个进程都不一样，
+    /// 重启一次就会在备份目录里多出一份同名文件。
+    /// </summary>
+    private static string StableSuffix(string text)
