+namespace BetterGenshinImpact.ViewModel.Windows;
+
+/// <summary>
+/// 桌面分身「诊断与修复」窗口的视图模型。
+///
+/// 面板只负责展示与触发：检查在 <see cref="ChildSessionEnvironmentCheck"/>，
