+    /// 单独占一行，不和 <see cref="StatusText"/> 抢：修完会立刻重新检测，
+    /// 状态栏马上变成「检查完成：…」，修复失败的原因就再也看不到了。
+    /// </summary>
+    [ObservableProperty]
+    [NotifyPropertyChangedFor(nameof(HasLastFixResult))]
+    private string _lastFixResult = string.Empty;
