+        }
+        finally
+        {
+            item.IsFixing = false;
+            IsBusy = false;
+        }
+
+        // 修复结果落在系统里，重新读一遍比「改本地列表」更可信。
+        await RecheckAsync();
+    }
+
+    /// <summary>
