+        // 面板属于桌面分身窗口，挂上去后跟随它一起关闭。
+        window.Owner = Application.Current.Windows.OfType<ChildSessionWindow>().FirstOrDefault()
+                       ?? Application.Current.MainWindow;
+        window.Closed += (_, _) => _diagnosticsWindow = null;
+        _diagnosticsWindow = window;
+        window.Show();
+    }
